import math

def check_condition(n):
    """Checks if k^2 === 1 (mod n) for all k coprime to n."""
    if n < 2:
        return False

    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check k^2 === 1 (mod n)
            if (k * k - 1) % n != 0:
                # Found a counterexample
                return False
    return True

